/*
  Reading requirements for the 29 test cases: 5898 (4101 enforced,
  3076 satisfied).
  Generated by models/hospital/readings_to_sql.py (rules in its docstring). Run after assignments.sql and
  authorisation/execution_properties.sql.
  Each row: the assignment, the property it is expected to record, ApplicationNetworkId 3 (the step), IsEnforced,
  Satisfied (it has a reading of it), CompletionDate (the last reading; NULL if none).
  Replaces the test cases' earlier requirements (@Reset = 1). If an assignment or property can't be found, the script
  lists them and writes nothing. Set @Commit = 0 for a dry run.
*/
USE [3b30813b-994f-4bb1-a70f-9763e2b61154];
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @Commit             bit              = 1;     -- 0 = dry run
DECLARE @Reset              bit              = 1;     -- 1 = replace the test cases' earlier requirements
DECLARE @OrganisationId     uniqueidentifier = 'DA8BA77A-AE36-43E0-A340-278B76345161';
DECLARE @AuthOrganisationId int              = 12;
DECLARE @ResultId           int              = 45;
DECLARE @CreatedBy          uniqueidentifier = 'A01AE24F-0301-4198-9036-8CC58F070B01';
DECLARE @Now                datetime2        = SYSUTCDATETIME();

DECLARE @rows TABLE (SpecName nvarchar(400), TeamName nvarchar(200), JobName nvarchar(200), ExecutorEmail nvarchar(256),
                     PropertyName nvarchar(200), IsEnforced bit, Satisfied bit, CompletionDate datetime2 NULL,
                     SpecId uniqueidentifier NULL, NodeId int NULL, ExecutorGuid uniqueidentifier NULL, ExecutorInt int NULL,
                     PropertyKey nvarchar(50) NULL);

-- The spec, the assignment's job node and executor, the property.
UPDATE r SET SpecId = s.Id FROM @rows r
JOIN [Results].dbo.Specs s ON s.Name COLLATE DATABASE_DEFAULT = r.SpecName COLLATE DATABASE_DEFAULT
                         AND s.ResultId = @ResultId AND s.OrganisationId = @OrganisationId;
DECLARE @jobNodes TABLE (Job nvarchar(200), Team nvarchar(200), NodeId int);
SELECT j.Job, j.Team, MIN(jn.Id)
FROM (SELECT DISTINCT JobName AS Job, TeamName AS Team FROM @rows) j
JOIN [Authorisation].dbo.SkillSets tk ON tk.Name COLLATE DATABASE_DEFAULT = j.Team COLLATE DATABASE_DEFAULT
                                     AND tk.NetworkId = 1 AND tk.OrganisationId = @AuthOrganisationId
JOIN dbo.Nodes tn ON tn.SkillSetId = tk.Guid AND tn.NetworkId = 1 AND tn.OrganisationId = @OrganisationId
JOIN [Authorisation].dbo.SkillSets jk ON jk.Name COLLATE DATABASE_DEFAULT = j.Job COLLATE DATABASE_DEFAULT
                                     AND jk.NetworkId = 2 AND jk.OrganisationId = @AuthOrganisationId
JOIN dbo.Nodes jn ON jn.SkillSetId = jk.Guid AND jn.NetworkId = 2 AND jn.ParentNodeId = tn.Id AND jn.OrganisationId = @OrganisationId
GROUP BY j.Job, j.Team;
UPDATE r SET NodeId = j.NodeId FROM @rows r JOIN @jobNodes j ON j.Job = r.JobName AND j.Team = r.TeamName;
UPDATE r SET ExecutorGuid = u.Guid, ExecutorInt = u.Id FROM @rows r
JOIN [Authorisation].dbo.Users u ON u.Email COLLATE DATABASE_DEFAULT = r.ExecutorEmail COLLATE DATABASE_DEFAULT
                                AND u.OrganisationId = @AuthOrganisationId;
UPDATE r SET PropertyKey = CONVERT(nvarchar(50), p.Id) FROM @rows r
JOIN [Authorisation].dbo.Properties p ON p.Name COLLATE DATABASE_DEFAULT = r.PropertyName COLLATE DATABASE_DEFAULT
                                     AND p.OrganisationId = @AuthOrganisationId AND p.PropertySubjectTypeId = 1;

-- AssignmentId takes a Guid or an Id, whichever its column is.
DECLARE @byGuid bit = CASE WHEN (SELECT t.name FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id
                                 WHERE c.object_id = OBJECT_ID('dbo.Assignments') AND c.name = 'ExecutorId') = 'uniqueidentifier'
                           THEN 1 ELSE 0 END;
DECLARE @asGuid bit = CASE WHEN (SELECT t.name FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id
                                 WHERE c.object_id = OBJECT_ID('dbo.AssignmentProperties') AND c.name = 'AssignmentId') = 'uniqueidentifier'
                           THEN 1 ELSE 0 END;
IF OBJECT_ID('tempdb..#requirement_rows') IS NOT NULL DROP TABLE #requirement_rows;
SELECT * INTO #requirement_rows FROM @rows;
ALTER TABLE #requirement_rows ADD AssignmentKey nvarchar(50) NULL;
DECLARE @find nvarchar(max) = N'
UPDATE r SET AssignmentKey = CONVERT(nvarchar(50), ' + CASE WHEN @asGuid = 1 THEN N'a.Guid' ELSE N'a.Id' END + N')
FROM #requirement_rows r JOIN dbo.Assignments a ON a.SpecId = r.SpecId AND a.NodeId = r.NodeId
 AND a.ExecutorId = ' + CASE WHEN @byGuid = 1 THEN N'r.ExecutorGuid' ELSE N'r.ExecutorInt' END + N';';
EXEC sp_executesql @find;

IF EXISTS (SELECT 1 FROM #requirement_rows WHERE AssignmentKey IS NULL OR PropertyKey IS NULL)
BEGIN
    SELECT DISTINCT TOP (50) SpecName, JobName, TeamName, ExecutorEmail, PropertyName,
           CASE WHEN SpecId IS NULL THEN 'spec not found (run the test cases)'
                WHEN AssignmentKey IS NULL THEN 'assignment not found (run assignments.sql)'
                ELSE 'property not found (run authorisation/execution_properties.sql)' END AS Problem
    FROM #requirement_rows WHERE AssignmentKey IS NULL OR PropertyKey IS NULL;
    DROP TABLE #requirement_rows;
    RAISERROR('Some assignments or properties could not be found (see grid): nothing written.', 16, 1);
    RETURN;
END

BEGIN TRANSACTION;

DECLARE @removed int = 0, @added int = 0;
IF @Reset = 1
BEGIN
    DECLARE @clear nvarchar(max) = N'
    DELETE x FROM dbo.AssignmentProperties x JOIN dbo.Assignments a ON x.AssignmentId = ' +
        CASE WHEN @asGuid = 1 THEN N'a.Guid' ELSE N'a.Id' END + N'
    WHERE a.SpecId IN (SELECT DISTINCT SpecId FROM #requirement_rows);
    SELECT @removed = @@ROWCOUNT;';
    EXEC sp_executesql @clear, N'@removed int OUTPUT', @removed OUTPUT;
END

                                      CreationDate, ModificationDate, CreatedBy, ModifiedBy)
SELECT r.AssignmentKey, r.PropertyKey, 3, r.IsEnforced, r.Satisfied, r.CompletionDate, @Now, NULL, @CreatedBy, NULL
FROM #requirement_rows r;
SET @added = @@ROWCOUNT;

SELECT @removed AS RequirementsRemoved, @added AS RequirementsAdded;
SELECT SpecName, IsEnforced, Satisfied, COUNT(*) AS Requirements FROM #requirement_rows GROUP BY SpecName, IsEnforced, Satisfied
ORDER BY SpecName, IsEnforced DESC, Satisfied DESC;
DROP TABLE #requirement_rows;

IF @Commit = 1 BEGIN COMMIT TRANSACTION;   PRINT 'Committed.'; END
ELSE           BEGIN ROLLBACK TRANSACTION; PRINT 'Dry run: rolled back.'; END
